create or replace view public.marketplace_listings with (security_invoker = true) as select w.id, w.slug, w.domain, coalesce(nullif(btrim(w.title), ''), w.domain) as title, coalesce(w.description, '') as description, coalesce(pc.slug, 'technology') as niche, coalesce(sec.slugs, '{}'::text[]) as secondary_niches, case when w.country_source = 'default' then null else w.country_code end as country, coalesce(w.language_code, 'en') as language, w.domain_rating, w.organic_traffic, w.referring_domains, w.organic_keywords, w.verified, w.completed_orders, w.created_at, w.link_attribute, coalesce(w.accepted_niches, '{}'::text[]) as accepted_niches, w.status, coalesce(w.audience_split, '[]'::jsonb) as audience_split from public.websites w left join public.categories pc on pc.id = w.primary_category_id left join lateral ( select array_agg(distinct c.slug) as slugs from public.website_categories wc join public.categories c on c.id = wc.category_id where wc.website_id = w.id and c.slug is distinct from coalesce(pc.slug, 'technology') ) sec on true;
comment on view public.marketplace_listings is 'The marketplace as the app sees it, not as the columns store it: country hidden when its source is "default", niche defaulted to technology, title falling back to the domain. security_invoker, so the websites policy decides what it returns.';
