art in lower( m.domain || ' ' || m.title || ' ' || m.description || ' ' || m.niche || ' ' || array_to_string(m.secondary_niches, ' ') )) > 0 ) from unnest( string_to_array(regexp_replace(lower(btrim(p_search)), '\s+', ' ', 'g'), ' ') ) as part where part <> '' ) ) and (p_niches is null or cardinality(p_niches) = 0 or m.niche = any (p_niches) or m.secondary_niches && p_niches) and (p_countries is null or cardinality(p_countries) = 0 or (m.country is not null and m.country = any (p_countries))) and (p_languages is null or cardinality(p_languages) = 0 or m.language = any (p_languages)) and ( coalesce(btrim(p_audience_country), '') = '' or exists ( select 1 from jsonb_array_elements(m.audience_split) as slice where upper(slice ->> 'country') = upper(btrim(p_audience_country)) and (p_audience_share_min is null or coalesce((slice ->> 'share')::numeric, 0) >= p_audience_share_min) and (p_audience_traffic_min is null or coalesce((slice ->> 'traffic')::numeric, 0) >= p_audience_traffic_min) ) ) and (p_link_attribute is null or m.link_attribute::text = p_link_attribute) and (p_dr_min is null or m.domain_rating >= p_dr_min) and (p_dr_max is null or m.domain_rating <= p_dr_max) and (p_traffic_min is null or m.organic_traffic >= p_traffic_min) and (p_traffic_max is null or m.organic_traffic <= p_traffic_max) and (p_rd_min is null or m.referring_domains >= p_rd_min) and (p_rd_max is null or m.referring_domains <= p_rd_max) and (not coalesce(p_verified, false) or m.verified) and (t.slug is null or m.accepted_niches @> array[t.slug]) and (p_link_types is null or cardinality(p_link_types) = 0 or pl.has_link_type) and ((p_price_min is null and p_price_max is null) or pl.price_in_window) and (p_max_turnaround is null or (pl.fastest_max_turnaround is not null and pl.fastest_max_turnaround <= p_max_turnaround)) ) select matched.id, count(*) over () as total from matched order by case when p_sort = 'kw-asc' then matched.organic_keywords end asc nulls last, case when p_sort = 'kw-desc' then matched.organic_keywords end desc nulls last, case when p_sort = 'price-asc' then matched.headline_price end asc, case when p_sort = 'price-desc' then matched.headline_price end desc, case when p_sort = 'dr-asc' then matched.domain_rating end asc, case when p_sort = 'dr-desc' then matched.domain_rating end desc, case when p_sort = 'traffic-asc' then matched.organic_traffic end asc, case when p_sort = 'traffic-desc' then matched.organic_traffic end desc, case when p_sort = 'rd-asc' then matched.referring_domains end asc, case when p_sort = 'rd-desc' then matched.referring_domains end desc, case when p_sort = 'turnaround-asc' then matched.headline_turnaround end asc, case when p_sort = 'turnaround-desc' then matched.headline_turnaround end desc, case when p_sort = 'newest' then matched.created_at end desc, case when p_sort = 'relevance' or p_sort is null then matched.relevance end desc, case when p_sort = 'relevance' or p_sort is null then matched.quality end desc, matched.domain_rating desc, matched.id asc limit greatest(1, least(coalesce(p_limit, 25), 100)) offset greatest(0, coalesce(p_offset, 0)); $$;
comment on function public.marketplace_search( text, text[], text[], text, integer, integer, text[], text[], text, integer, integer, integer, integer, integer, integer, integer, integer, integer, boolean, text, text, integer, integer ) is 'One page of the marketplace. Prices each candidate listing through the index on services(website_id) rather than pricing the whole marketplace first, and can narrow by where a publisher''s readers are as well as where the publisher is.';
